    n = len(distance_matrix)
    if n == 0:
        raise ValueError("Distance matrix cannot be empty.")

    def calculate_cost(route: list[int]) -> int:
        cost = 0
        for i in range(n - 1):
            cost += distance_matrix[route[i]][route[i + 1]]
        cost += distance_matrix[route[-1]][route[0]]
        return cost

    best_cost = float('inf')
    for start_city in range(n):
        visited = [False] * n
        route = [start_city]
        visited[start_city] = True
        for _ in range(n - 1):
            min_cost = float('inf')
            next_city = -1
            for city in range(n):
                if not visited[city]:
                    cost = distance_matrix[route[-1]][city]
                    if cost < min_cost:
                        min_cost = cost
                        next_city = city
            route.append(next_city)
            visited[next_city] = True
        cost = calculate_cost(route)
        best_cost = min(best_cost, cost)
    return best_cost

