    n = len(numbers)
    target_sum = sum(numbers) // 3
    ways = 0

    def backtrack(index: int, current_sum: int, row: int, cells: list[int]):
        nonlocal ways
        if row == 3:
            if current_sum == target_sum:
                ways += 1
            return

        if current_sum > target_sum:
            return

        for i in range(index, n):
            cells.append(numbers[i])
