        return ((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2 + (p1[2] - p2[2])**2)**0.5

    def projection(p: Tuple[float, float, float], line_start: Tuple[float, float, float], line_end: Tuple[float, float, float]) -> Tuple[float, float, float]:
        v1 = (line_end[0] - line_start[0], line_end[1] - line_start[1], line_end[2] - line_start[2])
        v2 = (p[0] - line_start[0], p[1] - line_start[1], p[2] - line_start[2])
        proj_len = (v1[0] * v2[0] + v1[1] * v2[1] + v1[2] * v2[2]) / (v1[0]**2 + v1[1]**2 + v1[2]**2)
        return (line_start[0] + proj_len * v1[0], line_start[1] + proj_len * v1[1], line_start[2] + proj_len * v1[2])

    max_sum = 0
    for a in range(4):
        for b in range(4):
            if a != b:
                M = (A[0] + (B[0] - A[0]) * a / 3, A[1] + (B[1] - A[1]) * a / 3, A[2] + (B[2] - A[2]) * a / 3)
                d_to_C = distance(M, C)
                d_to_D = distance(M, D)
                max_sum = max(max_sum, d_to_C + d_to_D)
    return max_sum

import numpy as np

def solve_gps_problem(A: tuple[float, float, float], B: tuple[float, float, float], C: tuple[float, float, float], D: tuple[float, float, float]) -> float:
    A, B, C, D = np.array(A), np.array(B), np.array(C), np.array(D)

    def distance_to_line(point: np.ndarray, line_start: np.ndarray, line_end: np.ndarray) -> float:
        v1 = line_end - line_start
        v2 = point - line_start
        proj = (np.dot(v2, v1) / np.dot(v1, v1)) * v1
        return np.linalg.norm(v2 - proj)

    def find_max_distance(A: np.ndarray, B: np.ndarray, C: np.ndarray) -> tuple[float, float, float]:
        max_dist = 0
        M = np.array([0, 0, 0])
        for t in np.linspace(0, 1, 100):
            M = A + t * (B - A)
            dist_to_C = distance_to_line(M, C, D)
            if dist_to_C > max_dist:
                max_dist = dist_to_C
                M_optimal = M
        return M_optimal

    M = find_max_distance(A, B, C)
    return M[0] + M[1] + M[2]

