import math

def calculate_probability(total_tickets: int, num_tickets_drawn: int) -> float:
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    prime_count = sum(1 for i in range(1, total_tickets + 1) if is_prime(i))

    def count_combinations(total: int, num: int) -> int:
        return math.comb(total, num)

    favorable_combinations = 0
    for i in range(2, num_tickets_drawn + 1):
        prime_count_in_combination = count_combinations(prime_count, i)
        non_prime_count_in_combination = count_combinations(total_tickets - prime_count, num_tickets_drawn - i)
        favorable_combinations += prime_count_in_combination * non_prime_count_in_combination

    total_combinations = count_combinations(total_tickets, num_tickets_drawn)

