def count_grid_ways(numbers: list[int]) -> int:
    n = len(numbers)
    target_sum = sum(numbers) // 3
    ways = 0

    def backtrack(row: int, current_sum: int, used: set[int]):
        if row == 3:
            return 1 if current_sum == target_sum else 0

        if current_sum > target_sum:
            return 0

        for num in range(n):
            if num not in used:
                used.add(num)
                ways += backtrack(row + 1, current_sum + numbers[num], used)
                used.remove(num)
        return ways

    return backtrack(0, 0, set()) 
