def maximize_profit_price(price: float, customers: int, price_change: int, customer_change: int, cost_coefficients: list) -> float:
    n = customers
    while True:
        new_price = price - price_change
        new_customers = customers + customer_change
        revenue = new_price * new_customers
        cost = cost_coefficients[0] * new_customers + cost_coefficients[1] * new_customers + cost_coefficients[2]
        profit = revenue - cost
        if new_price <= 0:
            break
        if profit > 0:
            n = new_customers
            price = new_price
        else:
            break
    return price / 1000

