import numpy as np

def solve_gps_problem(A: tuple[float, float, float], B: tuple[float, float, float], C: tuple[float, float, float], D: tuple[float, float, float]) -> float:
    A, B, C, D = np.array(A), np.array(B), np.array(C), np.array(D)

    def dist_to_line(P: np.ndarray, line_dir: np.ndarray, line_point: np.ndarray) -> float:
        v1 = P - line_point
        v2 = line_dir
        return np.linalg.norm(np.cross(v1, v2)) / np.linalg.norm(v2)

    def find_max_dist(A: np.ndarray, B: np.ndarray) -> tuple[float, float, float]:
        AB = B - A
        t = np.linspace(0, 1, 100)
        P = A + t * AB
        distances = [dist_to_line(P[i], AB, A) for i in range(len(t))]
        max_dist_index = np.argmax(distances)
        return P[max_dist_index]

    M = find_max_dist(A, B)
    return dist_to_line(M, (C - M), M) + dist_to_line(M, (D - M), M) + dist_to_line(A, (M - A), A)

