    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def calculate_combinations(total: int, k: int) -> int:
        return math.factorial(total) // (math.factorial(k) * math.factorial(total - k))

    prime_count = sum(1 for i in range(1, total_tickets + 1) if is_prime(i))
    total_combinations = calculate_combinations(total_tickets, num_tickets_drawn)
