    for i in range(2, num_tickets_drawn + 1):
        combinations_with_at_least_2_primes += calculate_combinations(prime_count, i) * calculate_combinations(total_tickets - prime_count, num_tickets_drawn - i)

    even_sum_combinations = 0
    for i in range(num_tickets_drawn // 2):
        even_sum_combinations += calculate_combinations(total_tickets, num_tickets_drawn) // 2

    probability = (combinations_with_at_least_2_primes * even_sum_combinations) / total_combinations
    return round(probability * 100, 1) 
